/**
 * Linhas de analise_quadro_linhas (forma do Prisma) para testes das fatias da Fase 1.
 * Números do banco dev de 29/09/2026 (arredondados). `linhaQuadroDb(over)` monta uma linha
 * completa; os nomeados cobrem os estados: calculado (WEGE3, ITUB4 financeira), incompleto (TGMA3),
 * zero_regra (AURE3), FII tijolo (HGLG11), sem_score (HCTR11), fora_do_indice (HFOF11) e ação
 * fora do Quadro (CEDO4).
 */
import { Prisma, type AnaliseQuadroLinha } from '@prisma/client';

export const GERADO_EM_FIXTURE = new Date('2026-09-30T10:40:00.000Z');

export function linhaQuadroDb(over: Partial<AnaliseQuadroLinha> = {}): AnaliseQuadroLinha {
  return {
    symbol: 'TEST3',
    classe: 'acao',
    cnpj: '00000000000000',
    dataRef: new Date('2026-09-29T00:00:00.000Z'),
    noQuadro: true,
    foraDoQuadroMotivo: null,
    temScore: true,
    estadoIndice: 'calculado',
    nome: 'Teste S.A.',
    nomeCurto: null,
    setor: null,
    subsetor: null,
    segmento: null,
    segmentoListagem: null,
    fiiTipo: null,
    segmentoCvm: null,
    regua: 'acao',
    tickerReferencia: null,
    preco: new Prisma.Decimal('10'),
    precoData: new Date('2026-09-29T00:00:00.000Z'),
    variacaoDiaPct: 0,
    volumeMedio21: new Prisma.Decimal('1000000'),
    baixaLiquidez: false,
    valorMercado: null,
    patrimonio: null,
    indiceMf: 5,
    criteriosAtendidos: 3,
    criteriosAplicaveis: 5,
    statusCriterios: [],
    motivosIncompleto: [],
    componentesZeroRegra: [],
    anosLucroConsecutivos: null,
    mesesComRendimento: null,
    anosDividendo: null,
    roePct: null,
    pl: null,
    pvp: null,
    dy12mPct: null,
    margemLiquidaPct: null,
    divLiqEbitda: null,
    divLiqPl: null,
    payoutPct: null,
    vacanciaFisicaCvmPct: null,
    nImoveisCvm: null,
    nCri: null,
    obrigacoesPlPct: null,
    cotistas: null,
    naoSeAplica: [],
    serie10a: [],
    serieUlt12m: null,
    pares: [],
    assetId: null,
    flags: [],
    paramsVersion: 1,
    geradoEm: GERADO_EM_FIXTURE,
    ...over,
  };
}

const serieAnual = (inicio: number, valores: Array<number | null>, suspeitos: number[] = []) =>
  valores.map((valor, i) => {
    const ano = inicio + i;
    return suspeitos.includes(ano) ? { ano, valor, suspeito: true } : { ano, valor };
  });

